#!/usr/bin/env python3\nimport argparse\n\nGHOST_FILES = [".env", ".git", ".ssh"]\n\ndef scan_image(image_name: str):\n    """\n    Pretend to scan a Docker image for ghost files.\n    Returns a list of found ghost file names.\n    """\n    # In a real implementation we would inspect the image layers.\n    # Here we simply return the predefined list for demonstration.\n    return GHOST_FILES\n\ndef main():\n    parser = argparse.ArgumentParser(description="Docker Ghostbuster scans images for leftover secret files.")\n    parser.add_argument("image", help="Docker image name to scan")\n    args = parser.parse_args()\n    print(f"Scanning image {args.image} for ghost files...")\n    for ghost in scan_image(args.image):\n        print(f"👻 Found {ghost}")\n\nif __name__ == "__main__":\n    main()
